/// Generic SDK projection derived from `ToolCandidate`.
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(bound(deserialize = "T: serde::Deserialize<'de>, P: serde::Deserialize<'de>"))]
pub struct Candidate<T = JsonValue, P = JsonValue> {
    #[serde(rename = "provenance")]
    #[serde(default, skip_serializing_if = "Presence::is_missing")]
    pub provenance: Presence<P>,
    #[serde(rename = "value")]
    pub value: T,
    #[serde(flatten)]
    pub additional_properties: BTreeMap<String, JsonValue>,
}

/// Generic SDK projection derived from `McpElicitationElicitResult`.
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(bound(deserialize = "T: serde::Deserialize<'de>"))]
pub struct ElicitResult<T = FormAnswers> {
    #[serde(rename = "_meta")]
    #[serde(default, skip_serializing_if = "Presence::is_missing")]
    pub meta: Presence<McpElicitationElicitResultMeta>,
    #[serde(rename = "action")]
    pub action: McpElicitationElicitResultAction,
    #[serde(rename = "content")]
    #[serde(default, skip_serializing_if = "Presence::is_missing")]
    pub content: Presence<T>,
    #[serde(flatten)]
    pub additional_properties: BTreeMap<String, JsonValue>,
}

/// Validated contextual responses; publication remains the runtime's responsibility.
#[derive(Debug, Clone)]
pub enum ContextualResponse {
    ConfigChangeBefore(Box<ConfigChangeBeforeInterceptResponse>),
    ContextCompactAfter(Box<ContextCompactAfterInterceptResponse>),
    ContextCompactBefore(Box<ContextCompactBeforeInterceptResponse>),
    ModelRequestBefore(Box<ModelRequestBeforeInterceptResponse>),
    ModelResponseAfter(Box<ModelResponseAfterInterceptResponse>),
    ModelSwitchBefore(Box<ModelSwitchBeforeInterceptResponse>),
    SessionStart(Box<SessionStartInterceptResponse>),
    TaskChangeBefore(Box<TaskChangeBeforeInterceptResponse>),
    ToolAfter(Box<ToolAfterInterceptResponse>),
    ToolBatchAfter(Box<ToolBatchAfterInterceptResponse>),
    ToolBefore(Box<ToolBeforeInterceptResponse>),
    ToolPermissionRequest(Box<ToolPermissionRequestInterceptResponse>),
    TurnFinishBefore(Box<TurnFinishBeforeInterceptResponse>),
    TurnStart(Box<TurnStartInterceptResponse>),
    UserElicitationRequest(Box<UserElicitationRequestInterceptResponse>),
    UserElicitationResult(Box<UserElicitationResultInterceptResponse>),
    UserMessageInbound(Box<UserMessageInboundInterceptResponse>),
    UserMessageOutbound(Box<UserMessageOutboundInterceptResponse>),
    WorkspaceChangeBefore(Box<WorkspaceChangeBeforeInterceptResponse>),
}
