/// Run application validation before returning a publishable response. No state is changed.
pub fn stage_response_for_request(
    event_type: EventType,
    input: &str,
    validate: impl FnOnce(&ContextualResponse) -> Result<(), String>,
) -> ParseResult<ContextualResponse> {
    match response_for_request(event_type, input) {
        ParseResult::Success {
            value,
            raw,
            mut diagnostics,
        } => match validate(&value) {
            Ok(()) => ParseResult::Success {
                value,
                raw,
                diagnostics,
            },
            Err(message) => {
                diagnostics.push(ParseDiagnostic {
                    path: String::new(),
                    code: DiagnosticCode::InvalidKnownVariant,
                    severity: DiagnosticSeverity::Error,
                    message,
                });
                ParseResult::Failure {
                    raw: Some(raw),
                    diagnostics,
                }
            }
        },
        failure => failure,
    }
}

